"""Generated documentation: ``docs/registry/schema.md`` (every table and column, each nullable column
with its reason, the views and triggers by name), ``docs/registry/vocabulary.md`` (every controlled
value with its evidence, plus the legacy-mapping table), ``docs/registry/records.md`` (the record
contract with the required fields per type). ``registry docs schema|vocabulary|records`` writes them;
tests assert the committed files are current.
"""
from __future__ import annotations

import os
import re
from typing import List

from . import identity as I
from . import records as R
from . import reducer as RD
from . import schema_def as S
from . import vocab as V

DOCS_DIR = os.path.join(os.path.dirname(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))),
                        "docs", "registry")

GENERATED_NOTE = "<!-- GENERATED by `registry docs {name}` from sisteer.registry.{source}; do not edit by hand. -->\n"

# The definitions' prose (schema_def.py docs and why-null reasons, vocab.py evidence) cites the design decisions it
# implements by id and date; the rendered pages state the rule without the citation.
_HISTORY_ID = r"(?:D\d{1,4}(?:-\d+)?[a-z]?|F\d{1,2}|S\d{1,2})"
_HISTORY_DATE = r"20\d\d-\d\d-\d\d"
_HISTORY_TOKEN = rf"(?:{_HISTORY_ID}|{_HISTORY_DATE})"
_HISTORY_PHRASES = (("; the D225 class", ""), (" (D62 follow-up)", ""), ("; D62 follow-up)", ")"), ("D24: ", ""))
_HISTORY_RES = (
    # a parenthetical that is only ids or dates: "", "", "(F10)", ""
    (re.compile(rf"\s*\({_HISTORY_TOKEN}(?:\s*(?:/|,|;|and)\s*{_HISTORY_TOKEN})*\)"), ""),
    # an id closing a parenthetical: "(…, <id>)", "(…; <id>)", "(… — <id>)"
    (re.compile(rf"\s*(?:[;,]|—|--)\s*{_HISTORY_TOKEN}(?=\))"), ""),
    # an id opening a parenthetical: "(migration 0020)"
    (re.compile(rf"\({_HISTORY_ID}\s*[;:,]\s*"), "("),
    # a date dating a clause, before the clause's own punctuation: "the ninth closing pass, 2026-10-10: the mover …"
    (re.compile(rf",\s*{_HISTORY_DATE}(?=[:;,])"), ""),
    (re.compile(r"[ \t]{2,}"), " "),
)


def history_free(text: str) -> str:
    """``text`` with its decision-id and date citations removed; the words of the rule itself are kept."""
    if not text:
        return text
    for old, new in _HISTORY_PHRASES:
        text = text.replace(old, new)
    for rx, repl in _HISTORY_RES:
        text = rx.sub(repl, text)
    return text.strip()


def _check_text(c: S.Column) -> str:
    parts = []
    if c.vocab:
        parts.append(f"`{c.vocab}`")
    if c.pattern:
        parts.append(f"pattern `{c.pattern}`")
    if c.fk:
        parts.append(f"→ `{c.fk[0]}.{c.fk[1]}`")
    return ", ".join(parts)


def render_schema_md() -> str:
    out: List[str] = [GENERATED_NOTE.format(name="schema", source="schema_def"),
                      "# Results registry — schema\n",
                      "The DDL is `src/sisteer/registry/schema.sql`, rendered from `schema_def.py`; a database is built from the "
                      "migration files in `src/sisteer/registry/migrations/` (`registry init`), never from `schema.sql` directly. This "
                      "page lists every table and column with its constraints and, for a nullable column, the reason it may be null; "
                      "the SQL of the table constraints, views and triggers is in `schema.sql`.\n",
                      "Conventions: every `CHECK (col IN (...))` list comes from `vocab.py` (`vocabulary.md`); booleans are INTEGER 0/1; "
                      "every `*_utc TEXT` is ISO-8601 UTC with milliseconds (`…Z`); every `*_json TEXT` is `json_valid`; hashes are "
                      "lowercase hex; foreign keys are enforced (sentinel columns by trigger). Item-scale tables carry `written_utc "
                      "INTEGER` (epoch ms) + `record_sha256 BLOB` as their order key and keep no history rows; their history is the "
                      "record log.\n",
                      "Scale classes: run-scale = " + ", ".join(f"`{t}`" for t in S.RUN_SCALE_TABLES) + "; item-scale = "
                      + ", ".join(f"`{t}`" for t in S.ITEM_SCALE_TABLES) + "; ledgers = "
                      + ", ".join(f"`{t}`" for t in S.LEDGER_TABLES) + "; staging (transient) = "
                      + ", ".join(f"`{t}`" for t in S.STAGING_TABLES) + ".\n",
                      "Soft reference (no DB FK, documented): `eval.default_item_set_id` → `item_set.item_set_id` is circular with "
                      "`item_set.eval_id` → `eval.eval_id`; enforcing both as dependency-blocking FKs would deadlock the seed.\n",
                      "## Tables\n"]
    for t in S.TABLES:
        out.append(f"### `{t.name}` ({t.scale}-scale)\n")
        if t.doc:
            out.append(history_free(t.doc) + "\n")
        out.append(f"Primary key: ({', '.join(f'`{c}`' for c in t.pk)})" + (
            "; unique: " + "; ".join("(" + ", ".join(f"`{c}`" for c in u) + ")" for u in t.uniques) if t.uniques else "") + "\n")
        out.append("| column | type | null | check / reference | note |")
        out.append("|---|---|---|---|---|")
        for c in t.columns:
            null = "NOT NULL" if c.nn else "nullable"
            if c.default is not None:
                null += f" default {c.default}"
            note = history_free(c.why_null if c.why_null else c.doc)
            out.append(f"| `{c.name}` | {c.type} | {null} | {_check_text(c)} | {note} |")
        extras = []
        if t.checks:
            extras.append("Table constraints: " + ", ".join(f"`{name}`" for name, _ in t.checks) + ".")
        if t.indexes:
            extras.append("Indexes: " + ", ".join(f"`{name}` ({', '.join(cols)})" + (f" where `{where}`" if where else "")
                                                 for name, cols, where in t.indexes) + ".")
        if extras:
            out.append("\n" + " ".join(extras))
        out.append("")
    out.append("## Views\n")
    out.append("Each view's SQL is in `schema.sql`; the second column lists the tables and views it reads.\n")
    out.append("| name | reads |")
    out.append("|---|---|")
    for name, _, refs in S.render_views():
        out.append(f"| `{name}` | {', '.join(f'`{r}`' for r in refs)} |")
    out.append("\n## Triggers\n")
    names = [m.group(1) for sql in S.render_triggers() for m in [re.search(r"CREATE TRIGGER (\w+)", sql)] if m]
    out.append("Triggers (SQL in `schema.sql`) enforce the foreign keys of sentinel-valued columns and the pairing of a run's "
               "state with its stamp and judgment: " + ", ".join(f"`{n}`" for n in names) + ".")
    return "\n".join(out).rstrip() + "\n"


def render_vocabulary_md() -> str:
    out: List[str] = [GENERATED_NOTE.format(name="vocabulary", source="vocab"),
                      "# Results registry — vocabulary\n",
                      "One noun per concept: **model** (a checkpoint at a pinned revision), **object** (the fitted or "
                      "declared intervention), **eval** (the benchmark only), **item_set** (its exact prompt set), **instrument** "
                      "(the declared measurement setting), **run** (one execution), **judgment** / **judge**, **paper_round**, "
                      "**substrate**. Every controlled value below is a `CHECK` list in the DDL and a validator rule; the evidence "
                      "column says what produces it.\n"]
    for name, values in V.VOCABULARIES.items():
        if name in ("BOOLEAN", "RECORD_TYPES", "LEDGERED_RECORD_TYPES", "ITEM_SCALE_TABLES", "RUN_SCALE_TABLES"):
            continue        # the record kinds are records.md's
        out.append(f"## `{name}`\n")
        ev = V.EVIDENCE.get(name, {})
        out.append("| value | evidence |")
        out.append("|---|---|")
        for v in values:
            out.append(f"| `{v}` | {history_free(ev.get(v, '—'))} |")
        out.append("")
    out.append("## Metric ids\n")
    out.append("`run_metric.metric_id`, `run_contrast.metric_id` and `eval.headline_metric_id` are free text scoped by the run's eval "
               "(`asr`, `over_refusal_graded`, `acc`, `petri_score`, `rate`; the eval is the qualifier, so `acc` on a gsm8k run is a "
               "complete name). The naming rule is a BANNED set, rendered as the `*_metric_id_not_generic` CHECK constraints and refused "
               "by name in `validate.py` before any insert (`vocab.banned_metric_ids()`):\n")
    out.append("- A bare generic noun names no statistic: " + ", ".join(f"`{v}`" for v in V.GENERIC_METRIC_IDS) + ".")
    out.append("- A degeneration statistic belongs in `run_degeneration` (measure × scope, with `measurement_state`) and reaches "
               "`run_metric` only through the `frac_*` mirror columns, never as a metric row under an unqualified spelling: "
               + ", ".join(f"`{v}`" for v in V.UNQUALIFIED_DEGENERATION_METRIC_IDS)
               + ", every `DEGENERATION_MEASURES` name as a bare id or as `frac_<measure>` / `<measure>_rate` / `<measure>_frac` / "
               "`<measure>_share` / `degen_<measure>_share`, the r2 export's own spellings of the statistics it files as metric rows ("
               + ", ".join(f"`{v}`" for v in V.LEGACY_DEGENERATION_METRIC_SPELLINGS) + "), and every "
               "mirror column name (" + ", ".join(f"`{v}`" for v in V.DEGENERATION_FRAC_COLUMNS) + ").")
    out.append("- An eval may accept more than one spelling of its headline: `eval.extra_json.headline_metric_ids` lists them in order of "
               "preference (seeded in `configs/registry/evals.yaml`; `strongreject_bon`: `asr`, then `asr_bon_cap4096`, threshold 0.5 "
               "both), and a consumer takes the first the run files, else `headline_metric_id` (`paper.headline_metric_ids`; "
               "`v_item_headline` applies the same rule in SQL). `headline_metric_id` stays the one declared id (NOT NULL, CHECK-guarded).")
    out.append("- Best-of-N rows are guarded at emission (`vocab.bon_metric_refusal`, called from `emit.RecordWriter.emit_metrics` and "
               "`hooks.JudgingScope.metrics`, never from the validator): `asr_bon_cap4096` at a threshold in {"
               + ", ".join(str(t) for t in V.BON_METRIC_THRESHOLDS["asr_bon_cap4096"]) + "}, `bon_nauc` in {"
               + ", ".join(str(t) for t in V.BON_METRIC_THRESHOLDS["bon_nauc"]) + "} (the AUC's no-threshold sentinel), `asr_at_n<N>` carrying "
               "`extra.bon_n` = N; the spelling " + ", ".join(f"`{s}`" for s in V.BON_LEGACY_METRIC_SPELLINGS) + " is refused for new records "
               "and its existing rows stay as legacy (`paper.METRIC_LEGACY` reads them as the `asr` curve point; `producer_metric_spelling` "
               "is the provenance).")
    out.append("- A producer's own spelling that differs from the registry id rides `producer_metric_spelling`. The r2 export adapter "
               "routes the export's degeneration metric rows (`adapters.r2_export.DEGENERATION_SPELLINGS`) into `run_degeneration` and "
               "mirrors the union instrument's readings onto the run's headline `run_metric` row; a qualified statistic no measure names "
               "(`residual_at_cap_share_bon_4096`, `at_cap_share_all`, `goal_*_share`, …) stays a metric row.")
    out.append("")
    out.append("## `fit_target_kind` pairing rules\n")
    out.append("| kind | required non-null | required NULL | `fit_objective` | `derivation` | equals |")
    out.append("|---|---|---|---|---|---|")
    for kind, rule in V.FIT_TARGET_RULES.items():
        eq = ", ".join(f"`{c}={v}`" for c, v in rule["equals"]) or "—"
        out.append(f"| `{kind}` | {', '.join(f'`{c}`' for c in rule['nonnull']) or '—'} | "
                   f"{', '.join(f'`{c}`' for c in rule['null'])} | {', '.join(rule['fit_objective'])} | "
                   f"{', '.join(rule['derivation'])} | {eq} |")
    out.append("\n## Derivation rules (`derive.py`)\n")
    out.append("- `transfer_kind`: `fit_model_id` vs `run.model_id` — same id → `instruct_direct`; fit on a base checkpoint served "
               "on an instruct one → `base_to_instruct`; chat checkpoint → `chat_checkpoint`; system instruction → `prompted_only`; "
               "none → `none`.")
    out.append("- `fit_positions`: sidecar precedence `train_budget_meta.json:positions` → `fit_provenance.json:positions_at_fit` → "
               "`fit_meta.json:positions` → blob `positions|steer_positions|fit_positions`; Arditi → `searched_post_instruction_span`; "
               "diff-mean / CAA / AlphaSteer → `last_token_of_appended_assistant_header`; derived kinds → `inherited_from_parents`.")
    out.append("- `applied_positions_mode`: natively served LoRA → `all`; native residual slot → the standup's served positions; lens → "
               "its served-positions key; AlphaSteer → `prefill_last_broadcast`; antidote → `last`; passthrough / none → `none`.")
    out.append("- `multi_turn_steering_scope`: on a multi-turn eval, `all` → `every_turn_prefill_and_decode`, `response` → "
               "`final_header_and_current_decode_only`, `response_all_turns` → `every_assistant_span`, prefill-only modes → "
               "`prefill_only_each_turn`; single-turn evals → `single_turn`; a `none` object, or a system-instruction object on a "
               "multi-turn eval (a prompted object steers no positions, whatever mode the row carries) → `not_applicable`. "
               "`history_resent_each_turn = 1` and `decode_scope = per_turn_request` on every current harness.")
    out.append("- `substrate`: a path under cluster A's shared root → cluster_a; under cluster B's → cluster_b (the site configuration names "
               "both roots); Modal volume → modal; other local paths → grading_host (`substrate_source = derived`).")
    out.append("- `fit_target_kind`: `derived_meta.json` present → `derived`; a dose stamp (`object.pt.provenance.json:dose_scale` or a "
               "`train_budget_meta.json:dose_scaled_from` block) → `derived`, read before the fit record because a dose-scaled copy carries its "
               "parent's `train_budget_meta.json`; `none` → `none`; `system_instruction` → `declared_prompt`; `fit_meta.json` or a contrastive kind → "
               "`contrastive_direction`; `train_budget_meta.json:si_id` naming a corpus → `corpus_document_fit`, naming a teacher the seeds know (an "
               "`si_text` row) with `teacher_forward` → `system_instruction_distillation`; both → refused as ambiguous; nothing → refused, keys listed.")
    out.append("- `decode_resolved_json`: un-sent keys filled from the served snapshot's `generation_config.json` as `not_sent_resolved_to`; "
               "a model with no file resolves to the engine defaults marked `assumed_default`.")
    out.append("- degeneration measures: classifier = `eval/degeneracy.py` tail/line loop; contentless = < 10 alphanumerics after unescape; "
               "rep-ratio loop = 4-gram repetition > 0.5; zlib collapse = compressed/utf8 < 0.15; union5 = OR of five; at-cap = "
               "`finish_reason == length`. `run_metric.frac_*` mirror `run_degeneration`'s `all`-scope rates, never the other way round, "
               "and stay NULL when the row's `measurement_state` is not `measured`.")
    out.append("- **`run_degeneration.measurement_state` — a consumer MUST branch on the state, never on a NULL rate.** "
               "`measured` rows carry numerator, denominator, denominator_unit and rate; `not_measured` / `not_applicable` / `refused` rows "
               "carry NULLs for all four (table CHECK `run_degeneration_measured_pairing`). `v_run_degeneration_wide` exposes "
               "`<measure>__<scope>_state` beside every `_rate`.")
    out.append("- structured `ruling.expires_when_json`: a single condition object, or `{kind: any_of|all_of, conditions: [...], "
               "guards: [...]}`; `guards` (`input_sha_pinned`, `served_record_at_ruled_point`) are evidence only and can never retire a "
               "ruling — a failing guard makes the evaluation `incoherent`; a condition whose evidence is missing / path-absent never counts "
               "as held.")
    out.append("- `roster_entry.strength_rule`: `operating_point` | `fixed:<x>` | `ladder:<record_id>` (every strength level the record carries).")
    out.append("\n## Decode surfaces\n")
    out.append("Three places state sampling numbers; one is the authority and the other two are derived from or checked against it:\n")
    out.append("| surface | status |")
    out.append("|---|---|")
    out.append("| `decode_policy` + `sampling_mode_policy` tables, exported to `configs/registry/decode_policy.json` (`registry decode-policy export`, "
               "hash-pinned, stamped with the registry `ingest_seq`; `registry decode-policy check`) | the authority; seeded from "
               "`configs/registry/decode_policy_seed.yaml` by `registry dimensions load` |")
    out.append("| `sisteer.capeval.tinycap.contracts` sampling tables (`SAMPLING_BY_MODEL_KEY`, `QWEN35_VENDOR_ROWS`, "
               "`SERVER_DEFAULT_SAMPLING_BY_MODEL`, `GREEDY_SAMPLING`, `PROTOCOL_SAMPLING_BY_TASK`), best-of-N's per-model vendor preset, "
               "the misalignment runner's samplers, the multi-turn target's greedy boundary | derived from the export at import through "
               "`sisteer.registry.decode_policy` (stdlib); `tests/test_registry_decode_policy_entry_points.py` pins equality with the oracle "
               "fixture under `tests/fixtures/registry/` and that a changed export changes the request bodies |")
    out.append("| `configs/sdfbase_sampled_decode.yaml` (`sisteer.eval.sampled_decode`, the sampled drivers' presets) | a separate statement, "
               "agreement-tested against the export-backed table (`tests/test_vendor_sampling_row_agreement.py`) |")
    out.append("")
    out.append("\n## Identity minting (`identity.py`)\n")
    out.append("Judge and instrument ids are minted by one function each, from canonical fields, by the seeds loader and every "
               "adapter alike, so a judgment's `judge_id` and a run's `instrument_id` join the dimension rows whoever wrote them.")
    out.append("- `identity.judge_id(judge_model, rubric_sha256, protocol_sha256, threshold_rule)` = sha256 hex over the canonical "
               "JSON (sorted keys) of exactly those four fields; a `judge` row may be passed as one mapping.")
    out.append("- `identity.instrument_id(fields)` = sha256 hex over the canonical JSON of every identity column of the `instrument` "
               "table, each normalised to its storage type before hashing (REAL → float so 0 == 0.0; INTEGER → int; JSON "
               "columns → the parsed value; None for an absent field): "
               + ", ".join(f"`{f}` ({t})" for f, t in I.INSTRUMENT_ID_FIELDS)
               + ". The alias spellings " + ", ".join(f"`{k}`→`{v}`" for k, v in I._INSTRUMENT_FIELD_ALIASES.items())
               + " fold onto the column names, so an `instrument` row, a seed row and a policy row mint one id. Only `notes`, "
               "`extra_json`, `field_confidence_json` and the harvester tail are outside the identity. "
               + ", ".join(f"`{f}`" for f in sorted(I.INSTRUMENT_ID_OPTIONAL_FIELDS))
               + " are omitted from the canonical JSON while NULL (`identity.INSTRUMENT_ID_OPTIONAL_FIELDS`): an unpadded instrument "
               "hashes as it did before the padding fields existed, and a padded one is another instrument "
               "(`padding_identity_sha256` = `identity.padding_identity_sha256(block)`, sha256 over the canonical JSON of the filler contract "
               + ", ".join(f"`{k}`" for k in I.PADDING_IDENTITY_KEYS) + ").")
    out.append("\n## Legacy-term mapping\n")
    out.append("Older words of the producing harnesses map to registry nouns as follows. This block is the one place they are spelled outside "
               "`_legacy` columns (the vocabulary test exempts it).\n")
    out.append("<!-- legacy-mapping -->")
    out.append("| legacy term | registry noun | where the legacy spelling survives |")
    out.append("|---|---|---|")
    for legacy, noun, where in V.LEGACY_MAPPING:
        out.append(f"| {legacy} | {noun} | {where} |")
    out.append("<!-- /legacy-mapping -->")
    return "\n".join(out).rstrip() + "\n"


def render_records_md() -> str:
    out: List[str] = [GENERATED_NOTE.format(name="records", source="records"),
                      "# Results registry — record contract\n",
                      "One JSON object per line, in append-only files that are never rewritten; a correction is a new record. Producers "
                      "write to a spool on their own storage and push each record directory to the registry host's inbox "
                      "(`scripts/registry/push_records.sh`, over a write-only `registry-push` key; the harvester can also pull). The record "
                      "files are the system of record; the database is a rebuildable index (`registry rebuild --verify`).\n",
                      "```\n{\"record_type\": \"run|run_patch|run_state|run_metric|run_contrast|item_result|item_flags|run_degeneration|judgment|"
                      "object|artifact|model|eval|item_set|instrument|judge|si_text|fit_search|fit_trial|paper_round|roster_entry|ruling|"
                      "decode_policy|sampling_mode_policy|computation|disposition|snapshot|<harvester types>\",\n"
                      " \"schema_version\": 1,\n \"record_id\": \"<uuid4 (producers) | uuid5 over the canonical payload (adapters, harvester)>\",\n"
                      " \"written_utc\": \"2026-09-16T18:04:11.312Z\",\n"
                      " \"producer\": {\"script\": \"…\", \"code_sha\": \"<40-hex>|unverified\", \"session\": \"<session or null>\", "
                      "\"host\": \"…\", \"substrate\": \"" + "|".join(V.SUBSTRATES) + "\"},\n"
                      " \"payload\": { …table columns…, \"extra\": { unknown fields } }}\n```\n",
                      "## Locations\n",
                      "- producer spool: `<shared root>/registry/records/<campaign>/<run_dir>/<seq>-<record_type>.jsonl[.gz]`",
                      "- registry root: `records/` is the merged log; harvester facts under `records/harvester/<utc-day>/`, adapter output "
                      "under `records/adapters/<adapter>/<revision_id>/`, claims under `records/claims/<run_dir>/`, hand-written "
                      "supersedes under `records/supersedes/<run_dir>/`; rulings under `rulings/*.jsonl`.",
                      "- `run_dir` = `identity.run_dir_name(run_id)`; `record_uri` is the root-relative logical path (no `.gz`).\n",
                      "## Identity and order\n",
                      "- `record_sha256` = sha256 over the record's canonical JSON (sorted keys, compact separators): the dedupe key "
                      "(`INSERT OR IGNORE`) and, with `written_utc`, the order key of every fold. Run-scale events fold in "
                      "`(written_utc, tie_rank, record_sha256)` order, where `tie_rank` is 1 for a `run_state` to a lateral or terminal state "
                      "(`failed`, `cancelled`, `superseded`, `withdrawn`) and 0 for every other record (`reducer.ORDER_SQL`); item rows take "
                      "`(written_utc, record_sha256)`.",
                      f"- The run-scale order has a VERSION, `reducer.FOLD_ORDER_VERSION` = `{RD.FOLD_ORDER_VERSION}`, recorded in the database "
                      "as the `schema_migration` row with `version = 0` (outside the migration sequence, which starts at 1, and invisible to "
                      "`MAX(version)`; `description` = the version string, `applied_utc` = when the stamp was made). The first WRITER stamps a "
                      "database that records none and proceeds (the bootstrap: every database from before the stamp, the live one at the next "
                      "harvester tick); every writer -- `db.open_or_create`, `harvest.fold_only_files`, a claim's fold, the replica's refold "
                      "writer -- refuses by name a database recording ANOTHER order (`db.FoldOrderDrift`, a `SchemaDrift`: both orders in the "
                      "message, nothing written), and readers never check. The remedy is a refold under the code's order (`registry rebuild` "
                      "stamps the fresh database as it creates it) or the code the database was folded by, never an edit of the row. "
                      f"The orders so far: {'; '.join(f'{n} = `{v}`' for n, v in sorted(RD.FOLD_ORDERS.items()))}. "
                      "`registry replica residual-class` lists the rows the pre-tie-break order left in `judged` where the current order gives "
                      "`superseded` (a same-stamp `superseded` event at the row's lifecycle stamp), read-only.",
                      "- `ingest_seq` is derived at file scale: the dense rank of a record file in arrival order "
                      "`(arrival_utc, first_written_utc, sha256, uri)`, where `arrival_utc` is the registry's clock at the file's first fold. "
                      "The cycle that folds a file writes a `file_arrival` fact for it (`records/harvester/<day>/file_arrival-<sha12>.jsonl`), "
                      "so a rebuild from any mirror reproduces the ranks; a file with no fact takes `arrival_utc = first_written_utc`. Every row "
                      "carries its file's rank.",
                      "- `run_id = identity.run_id(campaign, producer_key, producer_object_key, eval_id, instrument_id)` = "
                      "`<campaign>:<eval_id>:<instrument_id[:12]>:<sha16(producer_key|producer_object_key)>`; the producer's own keys are "
                      "kept verbatim in `producer_run_key_legacy` / `producer_object_key_legacy`.\n",
                      "## Validation\n",
                      "Envelope → required fields per type (table below) → strictness: a `run` naming `eval_id` without its `item_set_id` "
                      "or `instrument_id` is refused naming the field and the record path, never defaulted → every controlled field against "
                      "`vocab.py` (the same lists as the DDL CHECKs) → `unverified` admitted only with "
                      "`field_confidence_json[field] = {confidence: unverified, reason: …}` → secret-shaped payload keys refused → "
                      "unknown keys parked in `extra_json`, never dropped. A malformed record is refused (a `record_refusal`, below); a "
                      "well-formed record whose parent row is not yet folded (a `run_state` before its `run`, a `judgment` before its run, an "
                      "`object` before its `si_text` or parent object) is dependency-blocked: queued in `blocked_records`, re-evaluated "
                      "every cycle, never dropped.\n",
                      "A record carries finite numbers only: `NaN` / `Infinity` are not JSON, so a non-finite float anywhere in a record is "
                      "refused naming its field path; a number that does not exist is a measurement state, never a value. The adapter runner "
                      "makes free-form `extra` fields JSON-safe before it writes (`adapters/runner.py` `sanitise_free_form`); a typed column "
                      "is never touched.\n",
                      "Further rules refused by name:\n",
                      "- a `run` record's `code_sha` is the sha of the producing checkout, or `unverified` with a `field_confidence_json` entry; "
                      "forty identical hex digits is a placeholder and is refused (`validate.run_code_sha_refusal`).",
                      "- a `run` record stating `token_cap_rung_index` must state `token_cap_ladder_json` (a non-empty strictly ascending array "
                      "of positive integers), an index inside it, and `token_cap_tokens` (the cap the row was drawn at) equal to the indexed "
                      "level (`validate.run_cap_ladder_refusal`); none of the three is patchable, and `registry cap-check` reports the legacy "
                      "shapes against the instrument's ladder, read-only.",
                      "- a `judgment` record's `judgment_id` must equal `identity.judgment_id(run_id, judge_id, S, C)` for one of the forms "
                      "in use (`(None, None)`, `(claimed_by_session, claimed_utc)`, `(producer_session, claimed_utc)`), so a same-id record "
                      "naming another run or judge never folds. Records that predate a rule are admitted by sha "
                      "(`validate.GRANDFATHERED_RECORD_SHAS`), never by shape.\n",
                      "## Who writes what\n",
                      "- submit wrapper → `run` (planned identity, `lifecycle_state = queued`) + `run_state queued`",
                      "- job start → `run_state running` + `run_patch` (node, job id, GPU)",
                      "- serving standup → `run_patch` with the observed fields under `fields` and the immutable ones under `verify`",
                      "- store writer → `item_result` / `item_flags` rows (gz), `run_state generated` with the completion artifact",
                      "- grading → `judgment` (a claim is `status = in_progress`), `item_result` judge rows, `run_metric`, "
                      "`run_contrast`, `run_degeneration`, `run_state judged`",
                      "- fits → `object` (+ `fit_search`, `fit_trial`); dimension seeds → `model`, `eval`, `item_set`, `judge`, `instrument`, "
                      "`si_text`, `decode_policy`, `sampling_mode_policy`, `computation`",
                      "- a backfill adapter → the `run` record with `lifecycle_state = generated` (the state its store proves; a run record "
                      "admits queued | running | generated only) plus `run_state` events for judged / failed / cancelled, the `judgment`, "
                      "the metrics and the item rows, never a run record already at `judged`",
                      "- the harvester → `run_ingest` (only when the completion requirements hold), `file_arrival` (one per file folded), "
                      "`record_refusal` (one per refusal judgment), `ruling_state`, `source_watermark`, `source_state`, `source_revision`, "
                      "`observation`, `withdrawal`, `mirror_ack`, `snapshot`, `artifact` (published pages)",
                      "- the adapter runner → `source_status`: after every accepted read of a source, one row per paper source string the "
                      "adapter covers, revision-tagged like the item rows, so the paper's status objects are rebuilt from `v_source_status`",
                      "- a producer that filed item rows under the wrong run → `item_withdrawal` (below)",
                      "- `registry analysis file --spec` → `artifact` (the report and the page directories' files, registered first) then "
                      "`analysis`, `analysis_input`, `analysis_artifact` (migration 0029): a prefill-only or offline analysis filed over "
                      "ingested runs and objects, as ledger facts under `records/analyses/<day>/` -- see `analysis` facts below\n",
                      "## `run_patch`\n",
                      "`{run_id, fields: {…}, verify: {…}}`: every key of `fields` must be in `RUN_PATCHABLE_FIELDS` (the observed fields a "
                      "hook learns after creation); every key of `verify` must be in `RUN_VERIFIED_FIELDS` (the immutable fields a later hook "
                      "re-observes) and is compared to the run row: equal → recorded in `extra_json.verified_fields`, different → the patch "
                      "is refused naming the field and both values. An identity or lifecycle field under `fields` is refused (state moves only "
                      "through `run_state` records), and so is a derived field (`decode_match.stamp_run_rows` recomputes the decode-policy "
                      "pair from the run's recorded decode fields every cycle; patch the fields it is derived from instead).\n",
                      "- `RUN_PATCHABLE_FIELDS`: " + ", ".join(f"`{f}`" for f in R.RUN_PATCHABLE_FIELDS),
                      "- `RUN_VERIFIED_FIELDS`: " + ", ".join(f"`{f}`" for f in R.RUN_VERIFIED_FIELDS),
                      "- `RUN_DERIVED_FIELDS` (refused by name): " + ", ".join(f"`{f}`" for f in R.RUN_DERIVED_FIELDS) + "\n",
                      "A patch carries its stamps and provenance under `fields.extra_json`, merged key by key into the run's `extra_json` "
                      "(latest record wins per key); a top-level `extra` on a `run_patch` is not folded. `fields.extra_json` must be a JSON "
                      "object or its serialization, else the patch is refused by name (an explicit null is a statement and passes). A patch "
                      "folds by order key per column, so a later full `run` record that still carries the old values re-sets them: write the "
                      "patch after the producer's last `run` record. `n_items_planned` is patchable; the completion predicate reads "
                      "`COALESCE(n_items_generated, n_items_planned)`, so the patch decides whether a run counts as complete.\n",
                      "A `run_patch`'s `field_confidence_json` is read PER COLUMN, as the patch's columns are: each entry it carries replaces "
                      "the standing entry of its column (an entry of null withdraws the standing one), the entries of the columns it names "
                      "nothing about stand, and a column the patch states outright without an entry keeps its standing entry with the "
                      "`unstated` flag shed -- a full `run` record's JSON is the row's whole, as every statement is. So a hook that cannot "
                      "read the row states the provenance of what it patches and nothing else: the standup's endpoint record stamps the "
                      "served `applied_positions_mode` with a `recorded` entry (or `unverified` with the reason, when the served list is "
                      "not one mode) and, beside it, the `multi_turn_steering_scope` that follows from the served mode, the eval's category "
                      "and the object's kind, with its derivation (or `unverified` with the reason, when the category cannot be read) -- the "
                      "row's other entries ride along untouched, and an `unverified` value on a patch carries its reason in the patch "
                      "itself, which is what the validator requires. A patch that carries no `field_confidence_json` adds, replaces and "
                      "withdraws no entry, but it still states the columns it carries: the entries of the columns it leaves alone stand as "
                      "they are, flag included, and a column it states keeps its standing entry with the `unstated` flag shed -- so an "
                      "unmarked patch that restates a reader-supplied count without an entry of its own makes that count an unmarked "
                      "statement, and a later marked reader no longer refreshes it.\n",
                      "A STORE'S opening never restates a served mode. A `CellStore` that opens a run registered before it (the submit "
                      "wrapper's or the job-start registration's `run` record is in the log, and the store's identity carries the registered "
                      "run id) files its own full `run` record -- the hashes, the model revision, the store uri, the route -- and carries "
                      "`applied_positions_mode` and `multi_turn_steering_scope` on it as the PLAN'S copies, marked unstated "
                      "(`extra.unstated_columns`, `hooks.STORE_PLANNED_COLUMNS`): a store observes neither, the standup's endpoint record "
                      "does, and the production standup writes its endpoint before the evaluation store opens. Marked, the two columns "
                      "keep the value and the confidence entry an earlier unmarked statement supplied (the registration's, or the "
                      "endpoint's served mode and the scope that follows it) and apply, flagged, only where nothing stated the column yet; "
                      "the record's other columns fold as the store's statements, and its confidence entries merge into the row's beside "
                      "the standing ones instead of replacing the row's whole. Before the marker the store's copy of the plan folded over "
                      "the endpoint's `response` as `all` and its planned scope, and the record's confidence JSON erased the endpoint's "
                      "entries with it; a replay reproduced the loss. A store that is the run's FIRST registration (no registered run id in "
                      "its identity) states both columns as it always did. The marker is written on new records only, so nothing already "
                      "folded moves.\n",
                      "The served mode is read against the OBJECT'S KIND. The proxy's `served_positions` spells the mask it applies within a "
                      "forward, not the registry's whole-generation mode: on a prefill-only object the mask covers prompt rows alone, so the "
                      "proxy's `all` is the registry's `prefill_last_broadcast` on an AlphaSteer object and `prefill_all` on a static "
                      "direction served through the lens (its `last` is `prompt_last` there), while on a LoRA, a ReLU-steer or a vector "
                      "object the same `all` is every token of every prefill and decode. The endpoint patch therefore resolves the kind -- "
                      "the served runs file entry's `object_kind`, an `object_id` that spells one (`none`, `si:<sha>`), else the adapter the "
                      "endpoint's engine identity attests for the served key (`petri_source_kind`, the kind the export wrote into the "
                      "adapter's config) -- and hands the served mode to `derive.applied_positions_mode`, the one rule table (an AlphaSteer "
                      "object reads `prefill_last_broadcast` and an antidote `last` whatever mask the proxy spells; the anchor and a prompted "
                      "object `none`), after reading the lens path's spelling back for a static direction (`hooks.LENS_SERVED_SPELLING`, the "
                      "inverse of the proxy's `defense_cells.SERVED_MODE_BY_STEER_POSITIONS`). A served `all` or `last` with no kind to read "
                      "it against is `unverified` with the reason -- never recorded as every-token steering -- and every other served mode "
                      "(`response`, `response_all_turns`, `non_template`, `prefill_all`, `prompt_last`) names the same positions in both "
                      "vocabularies, so it reads as itself whether or not the kind is known.\n",
                      "A correction of the scope from the live row (`registry reconcile multi-turn-scope`) is HELD for a run while any "
                      "`run_patch` anywhere in the log that states its `applied_positions_mode` or `multi_turn_steering_scope` -- the pass's "
                      "own earlier correction, a standup's endpoint patch pushed but not yet ingested -- or any full `run` record there that "
                      "carries either column (a re-registration of the identity, an adapter's row, a store's opening with its marked copies: "
                      "whether a marked copy applies is the fold's call, which the pass waits for rather than predicts) is neither accepted "
                      "(`row_history`, the run's `run` and `run_patch` events alike) nor refused: folded in one ingest with a correction "
                      "derived from the row's old mode, the two would leave the row stating a served `response` beside a scope derived from "
                      "`all`. The walk reads the two record types' own files (`*-run.jsonl`, `*-run_patch.jsonl`, `.gz` too) under every "
                      "directory of the log. The dry run reports the run, the record's type and the columns it states, the apply writes "
                      "nothing for it and exits 2, and the run's own directory is read once more at the write; after the ingest the predicate "
                      "decides again from the folded row. The predicate is consistency, not the default value: a run of the class (a "
                      "multi-turn eval, `object_id != none`) whose scope differs from what the derivation reads from its own mode, category "
                      "and object kind is selected whatever stamped the value, and a consistent run gets no record. The hold cannot close "
                      "every race -- an endpoint patch published into another record directory after the pass's last read of the run's own "
                      "is seen by nothing, and the pass's later statement wins the fold -- so `registry reconcile multi-turn-scope --verify` "
                      "is the predicate alone over the folded database (read-only, no hold; exit 3 when it lists runs), and the landing window "
                      "runs the pass to a verified fixed point: apply, ingest, verify; a listed run reconciled once more from its folded mode, "
                      "ingested and verified again, which must read zero or the window fails by name with the runs.\n",
                      "`registry reconcile env-comments` restates the run-overrides stamp (`extra_json.run_overrides`) of every `run` row "
                      "whose stamp differs from the reading of ITS OWN overrides file. The overrides-file reader used to keep a value WITH its "
                      "inline comment (`\"64   # unchanged\"`); it now reads a `KEY=value` line as the shell does -- an unquoted value ends at "
                      "the first `#` preceded by whitespace, an empty value before a comment is the empty string, a quoted value is the quoted "
                      "span with a `#` inside it literal, a `#` with no whitespace before it is part of the value. The evidence is the file, "
                      "never the stored text: a stored `note #42` is what the reader makes of `'note #42'` and also what the old reader kept "
                      "of a one-word comment, so a value read as shell source again would lose legitimate content. The pass takes the files "
                      "(`--source`: a file or a directory of `.env` files; the repository's `reproduce/overrides` is always read), matches "
                      "each to the stamps by the file's `sha256` -- the digest the writer stamped is the bytes it read -- and writes one "
                      "`run_patch` per run whose stored `keys` (or `id`) differ from the matched file's reading -- every differing value "
                      "being what the OLD reader made of the file's line (the reader before the fix, read over the same file: the whole "
                      "right-hand side, surrounding quotes dropped), the artifact established per key and never assumed from the digest -- "
                      "carrying the WHOLE stamp "
                      "under `fields.extra_json.run_overrides` (the fold keeps a key's latest value whole: `path` and `sha256` stand, `keys` "
                      "are the file's reading, `id` the file's `OVERRIDE_ID`) beside a marker `reconciled_run_overrides_comments = "
                      "{replaced_keys: {KEY: <the value replaced>}, source_file, source_sha256, pass}` and a `field_confidence_json` entry on "
                      "`extra_json` naming the pass and the file. A stamp that is its file's reading already -- a quoted literal `#`, a value "
                      "the fixed reader stamped -- is never selected. Listed and NOT corrected: a stamp whose file is not given and whose "
                      "values may carry a comment (ambiguous: undecidable without the file); refused by name (unclassified), nothing of it "
                      "restated: a stamp whose file is given but whose key set is not the file's, or whose value under some key (or whose "
                      "`id`) is neither the file's reading nor the old reader's -- a later statement (a patch restating one key for one run "
                      "while keeping the file as provenance), which the digest and key set alone cannot tell from the artifact and which a "
                      "restatement from the file would overwrite. Only `run` is corrected: the stamp also rides the other tables' "
                      "rows (`run_state_event`, `judgment`, `run_metric`, `run_degeneration`, `object`, `fit_search`, `fit_trial`, "
                      "`item_result`), each a full statement folded per natural key with no patch kind, which the dry run counts per table "
                      "and never corrects. The hold is multi-turn-scope's: a run with an unfolded record anywhere in the log that states its "
                      "stamp (a full `run` record carrying it under `extra`, a `run_patch` carrying it under `fields.extra_json`, the pass's "
                      "own marker record) is held, exit 2 on `--apply`; `--verify`, with the same sources, is the predicate alone over the "
                      "folded `run` table (exit 3 when a selected, an unclassified or an ambiguous row remains). An unsourced stamp is not a "
                      "clean class: with no file given for any stamp (the sources unset, or a directory without the files the stamps were "
                      "read from) every polluted row is ambiguous, and a pass that counted only what it could decide would write nothing, "
                      "exit 0, and verify a class it had not touched; so an ambiguous row is refused by name on `--apply` (exit 2, nothing "
                      "written for it, the selected rows beside it still written) and listed by `--verify` (exit 3) until its file is given "
                      "or the operator leaves such stamps as stored by name (`--leave-unsourced`: listed, not a failure). `--check-sources` is "
                      "the coverage alone, read-only over the `run` table: every stamped row whose values may carry a comment has its file "
                      "among the sources (exit 0), or the uncovered stamps are listed by overrides id and file sha with their keys (exit 3); "
                      "the landing window runs it before anything moves when env-comments is listed for apply. "
                      "`run-patch-extra` compares a legacy stamp to the live one by the same evidence (the same `--source` files): two stamps "
                      "that differ are statements of one file -- `equal`, never `conflict` -- only when the file is given and each value of "
                      "both is one of the file's two readings, so a lost stamp with comment text and a live stamp restated from the file are "
                      "`equal`, a live value that is neither reading stays a `conflict` for the operator, and without the file only identical "
                      "stamps are equal; a stamp it re-files is the legacy record's own, which env-comments corrects from the file once "
                      "folded.\n",
                      "`registry reconcile fit-effective-batch` restates `fit_effective_batch` on every `object` row that carries the "
                      "MICRO-batch a sidecar hook read (`resolved_batch_size`) where the row's own `fit_hyperparameters_json` says the "
                      "optimizer width (`batch_size x accum_steps = effective_batch`, the value every other writer of the column states): one "
                      "same-id `object` record per row, written by the registry owner into `records/registry_owner/object__<sha16>/`, carrying "
                      "the row's required identity fields and the pairing columns its `fit_target_kind` requires (copied verbatim; the "
                      "validator admits nothing less), the recorded value, the row's WHOLE `field_confidence_json` with the column's entry "
                      "naming the source (the object table has no per-column confidence merge), and `extra.fit_effective_batch_correction = "
                      "{replaced, derived_from: {effective_batch, batch_size, accum_steps, resolved_batch_size}, pass}`; `status`, "
                      "`fit_hyperparameters_json` and every other column are omitted and keep their folded value and stamp. The class is a "
                      "function of the folded row alone (the two values disagree, the live value is the block's `resolved_batch_size`, the "
                      "block's own product is its `effective_batch`), so the correction is replay-equal and idempotent. Listed and NOT "
                      "corrected: the ambiguous rows whose column is NULL beside a recorded `effective_batch` -- dose-scaled copies, whose "
                      "`fit_effective_batch` the fit-sidecars adapter states as the PARENT's effective batch, `derived` from ONE source, the "
                      "parent's fit record copied beside the copy (the copy's own `train_budget_meta.json`, the record its block is read from; "
                      "the owner's ruling; the objects bank's re-emission is the correction, and a copy whose stated value equals its recorded "
                      "block is consistent), so an ambiguous row is one the adapter has not restated yet (no confidence entry for the column) or "
                      "left NULL by name (an `unverified` entry: the copied record names no integer `effective_batch` -- the key absent or null, "
                      "a float, a numeric string, a boolean; a record present and naming none is read as naming none, never skipped -- or the "
                      "copy carries no such record; the adapter states that NULL explicitly, so it replaces an earlier derived value rather than "
                      "leaving it beside a block it no longer agrees with -- and such a row is listed by that entry whether or not its block "
                      "records an `effective_batch`: the key absent or null, or no block at all, the recorded value shown as `-`; a dose copy "
                      "with no entry and no recorded value, and a row of another derivation left NULL by its own writer, are outside the "
                      "class), told apart in the report, where every ambiguous row is listed under "
                      "its group by object id with the row's own reason, in the text and the JSON alike, beside the group's count; a disagreeing "
                      "row whose column is marked `derived` (read from the entry's confidence, whichever writer stated it), or marked "
                      "`unverified` with a value still standing (a retained earlier statement), is not the hook's statement and is unclassified, "
                      "refused by name; a disagreement outside the hook's signature, or one whose five batch values (the column, the block's `effective_batch`, "
                      "`resolved_batch_size`, `batch_size`, `accum_steps`) are not all integers in the record's own type (a float, a numeric "
                      "string, a boolean, an unstated key), is unclassified and refused by name with the value and its type: nothing is coerced "
                      "or truncated, and the row stays listed (`--apply` exit 2, `--verify` exit 3) rather than dropped from the report. The "
                      "hold reads every `object` record "
                      "of a selected object anywhere in the log (the adapters' bundles included) that the fold has neither accepted nor "
                      "refused; `--verify` is the predicate alone over the folded `object` table (exit 3 when rows remain). The parent "
                      "cross-check, read-only in the dry run and the verify alike: every dose copy (`derivation = 'dose_scale'`) whose "
                      "`fit_effective_batch` is a `derived` statement is read against its PARENT object row -- the parent by the copy's "
                      "`parent_object_ids_json` (its one id), else `parent_object_id`; the parent's recorded effective batch its own "
                      "`fit_hyperparameters_json.effective_batch`, else its `fit_effective_batch` -- and every copy whose derived value is not "
                      "the parent's is listed by object id with both values, the two read in their own type as everywhere in this pass: a parent "
                      "recording an effective batch that is not an integer (`8.0`, `true`, `\"8\"`) beside a copy deriving `8` is a disagreement "
                      "listed with the value and its type, never an agreement, and nothing is coerced (`--verify` exit 3 while one stands; "
                      "`--apply` never writes for it: "
                      "the adapter's one source is the record copied beside the copy, so whether that copy is faithful to the parent the stamp "
                      "names is the registry's to say from the two rows it holds, and the operator's to read). A parent row absent from the "
                      "registry is not a disagreement and is said so by name; a parent present that states no effective batch, or a copy that "
                      "names no parent, is counted, not listed. The statement check, read-only beside it: the adapter's `derived` entry claims "
                      "the column IS the block's own `effective_batch` and its `unverified` entry claims the column is NULL, and the class SQL "
                      "asks neither (it selects a row whose two values disagree by SQLite's equality, which reads `8` and `8.0` as one value "
                      "and a missing key as nothing to compare), so every dose copy whose column carries a `derived` entry, and every one "
                      "whose `unverified` entry has a value standing beside it, is read against its OWN column and block in Python, in their "
                      "own type: a derived copy is consistent only when both are one integer that is not a boolean, the same on both sides, "
                      "and otherwise is listed by object id with which side fails -- the column NULL beside the derived entry, the column not "
                      "an integer, the block recording no `effective_batch` (the key absent or null, or no block; such a copy is not counted "
                      "as nothing to compare), the block's value not an integer (`8.0`), another integer -- and a value standing beside the "
                      "NULL-by-name entry is listed as such whatever the block says; `--verify` exit 3 while one stands, `--apply` never "
                      "writes for it (the adapter's re-emission is the correction), and a copy the class SQL also selects is one row, listed "
                      "once. An `unverified` entry beside NULL is the adapter's statement to the letter and is in the ambiguous class instead.\n",
                      "## `extra.unstated_columns`: a carried value that is not a statement\n",
                      "An `object` or `run` record may mark columns it carries but does not state: `\"extra\": {\"unstated_columns\": "
                      "[\"status\"]}`, a non-empty list of that table's non-key column names, each present in the payload (else refused by "
                      "name). A marked column fills a missing or null value and is skipped over a standing one, together with its "
                      "`field_confidence_json[c]` entry and `extra.<c>_origin` key, so a row never claims evidence for a value it does not "
                      "carry; on `run` the fold records `\"unstated\": true` inside the entry, a marked column may replace another marked "
                      "statement but never an unmarked one, and a marked null withdraws a value the same reader filed. `field_confidence_json` "
                      "itself can never be marked. The marker is a fold directive, never parked in `extra_json`; a `run_patch` may carry it in "
                      "`fields.extra_json`.\n",
                      "An `object` record may omit `status` and every other producer-owned column (`fit_code_sha`, `derivation_params_json`): "
                      "a mirror states nothing it did not read verbatim. A record omitting `status` folds normally when a row exists and is "
                      "dependency-blocked on its own row when none does; an explicit `status: null` is refused by name.\n",
                      "## A list column every record adds to, never restates: `artifact.locations_json`\n",
                      "`artifact.locations_json` is a UNION column (`reducer.UNION_COLUMNS`): EVERY `artifact` record, from every producer -- an "
                      "adapter's input registration, a hook's completion or weights artifact, the status page's own, `publish.register_files`, "
                      "`registry analysis file`, a record written by hand -- ADDS the entries it names to the standing list instead of replacing the "
                      "list (`reducer.union_payload`, `reducer.union_json_list`): an entry whose key -- a location's `uri`, a bare path itself, the "
                      "canonical JSON of anything else -- is new is appended in the record's order, a VERIFIED entry (a location with a non-null "
                      "`verified_utc`) replaces the standing entry of its key in place, an unverified one never does; a record carrying the column as "
                      "null over a standing list says nothing about the list (the list and its stamp stand), and over no standing value folds null. "
                      "A pure function of the record and the state before it, so a replay gives the same row whatever the arrival order, and the "
                      "row's list is the union of every record's in stamp order. No producer narrows a list on purpose -- a location that no longer "
                      "holds the bytes is the readers' concern (`publish.registered_shas` lets the bytes at a path pick the registration) -- so there "
                      "is no replacement directive. The column's SHAPE is checked on every `artifact` record, marker or none "
                      "(`validate._check_union_column_shapes`): a non-null `locations_json` in any shape but a JSON list -- an object, a scalar, a "
                      "string encoding either -- is refused by name, naming the column, because the union reads any other shape as NO entries, and "
                      "a record so shaped would otherwise fold as an accepted artifact whose location had vanished, evidence lost with no refusal "
                      "(a hand-written record carrying its one remote location as a JSON object, say). The marker `\"extra\": {\"union_columns\": "
                      "[\"locations_json\"]}` is admitted on `artifact` "
                      "records (a non-empty list of the table's union columns, each carried in the payload as a JSON list; anything else is refused "
                      "naming `extra.union_columns`) and names what the fold does anyway; it is a fold directive, not a park, and never lands in "
                      "`extra_json`. The union is the FOLD's rule, never a per-record directive the publish writers alone carry, so it holds for a "
                      "record without the marker: two filings of one known digest from two cluster paths folded in either order hold both paths, "
                      "and an adapter revision re-registering an unchanged input (a record naming the adapter's own locations alone) adds to the "
                      "list rather than replacing it, so the location an analysis filed for the same bytes stands and the filed copy publishes as "
                      "registered.\n",
                      "## `object` lineage\n",
                      "`object.parent_object_id` (a foreign key to `object.object_id`) and `object.named_role` (`vocab.OBJECT_NAMED_ROLES`: "
                      + ", ".join(f"`{v}`" for v in V.OBJECT_NAMED_ROLES) + ") are the epoch-checkpoint lineage. The fold sets each from the "
                      "record's own field when stated, else lifts it from `extra.parent_object_id` / `extra.named_role`; an explicit null resets, "
                      "and the latest statement per column wins. The parent is a dependency: a child whose parent has not folded waits in "
                      "`blocked_records`. Refused by name: a `named_role` outside the vocabulary; a `parent_object_id` equal to the object's own "
                      "id.\n",
                      "## `item_withdrawal`\n",
                      "A producer retracts `item_result` rows it filed under the wrong run:\n",
                      "```\n{\"run_id\": \"<the run the rows were filed under>\",\n"
                      " \"items\": [{\"item_id\": \"…\", \"metric_id\": \"…\", \"trial_index\": 0, \"sample_index\": 0, \"turn_index\": -1, "
                      "\"judgment_id\": \"\"}, …],\n"
                      " \"reason\": \"<free text, required>\",\n \"evidence_uri\": \"<optional>\",\n"
                      " \"belongs_to_run_id\": \"<optional: the run the rows should have been filed under; a name, not a foreign key>\"}\n```\n",
                      "- `items` is a non-empty list of exact item keys, the `item_result` key without `run_id` and the revision tag ("
                      + ", ".join(f"`{f}`" for f in R.ITEM_WITHDRAWAL_KEY_FIELDS) + "); `item_id` and `metric_id` are required, an absent index "
                      "takes the `item_result` default (`trial_index` 0, `sample_index` 0, `turn_index` -1, `judgment_id` ''). Refused by name: "
                      "a missing `run_id` / `items` / `reason`, an empty `items`, a key with a field outside the six or a non-integer index, a "
                      "key repeated in one record.",
                      "- Fold: one `item_withdrawal` row per key (the latest record naming a key stands), and the natively emitted `item_result` "
                      "row of the key (`source_revision_id = ''`) takes `withdrawn_by_record_sha256` / `withdrawn_reason` iff its order key is "
                      "below the record's; `v_item_result_current` and everything built on it exclude a marked row, the raw table keeps it, and "
                      "a row re-filed with a greater order key stands again. A withdrawal whose run or row has not folded yet waits in "
                      "`blocked_records`; `v_paper_inputs_head` counts `item_withdrawal` ranks, so the paper rebuild follows it.\n",
                      "## `record_refusal` facts\n",
                      "A refusal is a judgment the harvester makes about one record under one judging stamp (`harvest.validator_stamp`: the "
                      "DDL, the schema version and the validator / records / vocabulary / reducer / harvester sources). The ledger "
                      "`record_refusal` keeps the current judgment per record (`judged_with` names the stamp; a re-attempt under a new stamp "
                      "replaces the row), and every judgment is also written into the log as a `record_refusal` record under "
                      "`records/harvester/<day>/record_refusal-<sha12>.jsonl` and folded into `record_refusal_fact` (one row per refused "
                      "record and stamp), so every mirror and rebuild carry every refusal ever made. Payload: `record_sha256`, `record_uri` "
                      "(`<file>#<line>`), `record_type?`, `field?`, `reason`, `judged_with` (16 hex, or `unverified`), `refused_utc`, "
                      "`producer_json?`, `cycle_utc` (outside the minted id, so two cycles deriving one judgment mint one record). The kind is "
                      "in neither ledger's `record_type` CHECK list (`vocab.LEDGERED_RECORD_TYPES` = `RECORD_TYPES` without "
                      "`vocab.UNLEDGERED_FACT_TYPES`). Read back with `registry refusals list | explain | summary`.\n",
                      "## `analysis` facts (migration 0029)\n",
                      "An ANALYSIS is a prefill-only or offline computation -- a routing capture, a clamp ablation, an efficiency study -- with "
                      "results but no run-shaped home (no eval, no generation). It is filed by `registry analysis file --spec <json>` as three "
                      "LEDGER-FACT kinds, one row of one table each, folded by the same apply path as `record_refusal` (INSERT OR IGNORE, no "
                      "`row_history`, no field stamps: the row IS the fact), and listed in `vocab.UNLEDGERED_FACT_TYPES` so the two ledgers' "
                      "`record_type` CHECK lists are untouched (the 0029 migration is five CREATEs -- the three tables, the harvester's "
                      "`ordered_fact_record` index of their records and its `ordered_fact_carrier` audit of every file that carried one -- "
                      "and no rebuild). `analysis` {analysis_id, "
                      "name, code_sha, code_ref?, cluster_job_ids_json, substrate, report_uri?, report_sha256?, filed_utc, filed_by, notes?, extra: "
                      "{provenance: {kind: user_direct|relayed, relayed_by?, message_utc?}, decision, spec_sha256, …}}: `analysis_id` is "
                      "uuid5 over canonical JSON of {name, code_sha, inputs} (`sisteer.registry.analysis.analysis_id`), so a re-filing of the same "
                      "analysis is a duplicate at the fold and a changed input set or code sha is a NEW analysis (the normalized spec's input lists "
                      "are SORTED, so `extra.spec_sha256`, the hash of the normalized spec, is one hash for one input set whatever order the spec "
                      "lists the ids in, and a re-filing with two ids swapped is a duplicate of the filing, never a conflicting re-filing; the "
                      "artifacts and the cluster job ids keep the spec's order); `report_uri` and `report_sha256` "
                      "are filed together or not at all (the sha is computed for a local file, DECLARED in the spec for a report on cluster "
                      "storage -- never a guess; a remote report with no declared sha refuses the filing by name). `analysis_input` {analysis_id, "
                      "filing_sha256, input_kind: run|object, input_id, run_id?, object_id?}: the input named twice -- in the key and in the FK column "
                      "of its kind (the other null; the table CHECK pairs them) -- so `validate.parent_references` reads the parent through the "
                      "declared FK; `filing_sha256` is the record sha of the `analysis` header that wrote it (rule 9 below). "
                      "`analysis_artifact` {analysis_id, filing_sha256, artifact_id, role: report|page|figure, extra: {page_url?, page_dir?, relpath?, "
                      "declared_sha256?}}: the link to an `artifact` row the SAME filing registered ahead of it through `publish.register_files` "
                      "(kind by suffix; a page directory file by file, subdirectories included; a remote report under its declared sha, its "
                      "location unverified). The filing writes its records through one `RecordWriter` into a directory of its own, "
                      "`records/analyses/<day>/<filing>/` (`<filing>` the first twelve hex of the header's record sha; rule 10 below) -- the "
                      "artifact file, then the analysis, its inputs, its links -- with strictly increasing stamps and sequence numbers, so the "
                      "fold meets every FK parent before the row that names it, by path order and by stamp order alike. The database is READ for "
                      "the input check (every `inputs.runs[]` / `inputs.objects[]` id must be a row; a missing one refuses the filing by name and "
                      "writes nothing; `--dry-run` prints the plan and writes nothing) and never written: the harvester folds the records on its "
                      "next cycle. A ledger-fact kind cannot WAIT in `blocked_records` (its `record_type` CHECK is the ledgered list), so a "
                      "hand-written `analysis_input` or `analysis_artifact` naming a parent the registry does not hold is REFUSED by name at the "
                      "fold (the FK column, the parent table, the id; `harvest.Ingestor.apply_validated`), never queued -- a refusal fact like any "
                      "other. Ten rules govern a filing and its fold: (1) the filings fold in the cycle's LATE phase, "
                      "after the plain files, the revision directories and the blocked-queue pass, on live ingest and on rebuild alike "
                      "(`harvest.partition_analysis_files`), so an input whose run rides an adapter revision directory meets its parent on "
                      "both paths; (2) a dependency refusal is RE-SELECTED every cycle (`harvest.Ingestor.retry_dependency_refusals`: the "
                      "reason names the parent, `dependency: <table> <id> is not in this registry`) and the record accepted from its immutable "
                      "file once the parent exists -- its `record_refusal` row withdrawn, its refusal fact kept as history; (3) every row of the "
                      "three tables is kept by the LOG's order, not by first arrival (`records.LEDGER_ORDERED_TABLES`; the derived columns "
                      "`record_written_utc`, `record_sha256`, `record_uri` on each): among the records of one natural key -- an analysis_id, an "
                      "input of it, a link of it -- the smallest (written_utc, record_sha256) is kept, so the live apply replaces a standing row "
                      "when the incoming record sorts earlier and refuses by name -- `conflicting re-filing of <table> <key>: <columns> differ "
                      "from the kept filing <sha12>` -- the record that sorts later with another payload (the displaced one, or the incoming "
                      "one), while an identical payload is a duplicate (`filed_utc`, the filing's own clock, is never compared: a re-run of the "
                      "command on the same spec is a duplicate; a link's role and page url and an input's `extra_json` are substance); (4) every "
                      "record of the three the fold applies is indexed by its key in `ordered_fact_record` (sha, uri, stamp; the smallest uri "
                      "when one record arrives under two names), and when the kept record of a key moves EVERY other record of the key is "
                      "judged again against it from its immutable file -- an identical one accepted (its conflict refusal withdrawn), one that "
                      "differs refused by name, a former duplicate of the displaced record included, a still-conflicting one re-worded -- so "
                      "the rows, the index and the refusal table are the same sets on live ingest and on rebuild (were the header alone "
                      "ordered, or only the standing conflict refusals judged again, a link filed twice with another role would keep its first "
                      "arrival and a duplicate of a displaced filing would stand unrefused while a rebuild refused it); and the DELIVERY AUDIT "
                      "of a record's file (`record_delivery`, the status page's recent-ingests list) "
                      "follows every verdict judged again after the file's fold -- a filing displaced, a re-filing or a child (rule 9) judged "
                      "again, a dependency refusal (rule 2) accepted on retry: the record leaves its file's accepted count for `n_refused` or "
                      "returns as the apply judged it (`ok` or `duplicate`), and the status is derived again by the fold's own rule "
                      "(`harvest.Ingestor._move_record_delivery`, `harvest.delivery_status`; the cycle report's `deliveries_rejudged` counts "
                      "the moves) -- in EVERY file that carried the record: each arrival of a record of the three tables is entered in "
                      "`ordered_fact_carrier` (its uri and the side, `accepted` or `refused`, of its file's counts it stands on; "
                      "`vocab.DELIVERY_SIDES`) as the fold counts it, and the move reads the carriers from there, where `ordered_fact_record` "
                      "keeps one canonical carrier per record -- so `n_refused`, the accepted total and the status read what the record log "
                      "says of the file, as the row a rebuild writes does, and the carrier table itself is rebuild-equal (a record's standing "
                      "verdict per file that carried it); the `ok` / `duplicate` split among a file's accepted records stays the fold's "
                      "arrival order on either path (a second copy of an accepted record is counted `duplicate`), the reason the audit "
                      "itself is outside rebuild equality (without the move a displaced filing's header, input and link files would keep `ok` "
                      "with `n_ok` 1 while every record of them stood refused, and the status page would list the rejected filing as ingested; "
                      "were the move to follow the index's one carrier alone, a filing copied to a second uri and then displaced would keep "
                      "`ok` in the other file, which the page would list as ingested); (5) an artifact whose digest the registry ALREADY holds is LINKED, never "
                      "re-registered from what the "
                      "filing alone sees (`analysis.merge_known_artifacts`, `publish.merged_artifact_payload`): a full `artifact` record overwrites "
                      "the scalar columns it states, so its record for a known digest keeps the standing `kind` and `uri_primary` (a filing never "
                      "moves another registration's primary), states `bytes` / `verified_utc` only from a local capture and otherwise omits them so "
                      "the fold keeps the standing values, never states `created_utc` (the standing row's), and a filing whose location adds nothing "
                      "to the standing list writes NO artifact record (the link names the standing row; `--dry-run` and `--json` mark each known "
                      "artifact), so a remote report declaring a known digest neither nulls the standing row's `bytes` / `verified_utc` nor "
                      "replaces its verified local location with the one unverified cluster uri; (6) the LOCATIONS are the fold's "
                      "union, never a filer's snapshot: every artifact record `registry analysis file` and `publish.register_files` write names the ONE "
                      "location its writer sees, and the fold unions `artifact.locations_json` on EVERY artifact record from every producer "
                      "(`reducer.UNION_COLUMNS`, below), so the row's `locations_json` is the union of every record's in stamp order -- two analyses "
                      "filing one digest from two cluster paths before a fold, a remote declaration beside a local read of a digest nobody holds yet, "
                      "or an adapter revision re-registering the same bytes after a filing, fold to every location whatever their order, live and on "
                      "rebuild alike; a remote record omits the verification columns rather than stating them null, so it never un-verifies a row a "
                      "local read verified in the same window, and no `extra.remote` flag is stored (the null columns say it). A filer never "
                      "restates the standing locations read from the database at filing time (of two such filings folded before an ingest the "
                      "second would replace the first's path, and a rebuild would replay the same payloads to the same loss), and the union is "
                      "not a directive the publish writers alone carry (an adapter's record without it would erase a filed location); (7) the SAME bytes under several entries of one "
                      "filing -- two page directories with an identical `index.html`, a figure both pages serve, a report also inside its page "
                      "directory -- are ONE link ((analysis_id, artifact_id) is the key) carried by the FIRST entry of the digest, whose `role` and "
                      "page keys the link states, and every further entry is listed in the link's `extra.same_bytes` ({uri, role, page_dir?, "
                      "relpath?, page_url?} each, `analysis.SAME_BYTES_KEY`; `registry analysis list` and the status page read the page urls from "
                      "both, skipping an entry that is not an object, and the validator refuses a new link carrying the key in any other shape by "
                      "name, so one accepted link whose entries were path strings cannot fail the whole listing and the status page's Analyses "
                      "section); every further DISTINCT path still writes its own artifact record -- its location is a "
                      "fact the union keeps, the first "
                      "path the row's primary and the first entry's kind its kind, so the row is the same whatever order the fold meets the "
                      "records in -- and a further entry of the same path adds no record; a digest seen once is never dropped on its next path, "
                      "so a second page with the first's bytes is registered and its url reaches the link; (8) a file is REGISTERED at a path "
                      "when an artifact row names the path as its primary or among its locations "
                      "(`publish.registered_shas`; a location entry is a bare path or an object's `uri`), the bytes checked against the sha "
                      "either way: since a filing never moves the standing primary (rule 5), a local copy read after a remote declaration of its "
                      "bytes lives in the row's locations alone, and `publish_dir` reads it there as registered; "
                      "and the bytes at a path pick its registration among EVERY row naming the path -- an earlier file at the path stands as "
                      "its row's primary while a later file's row names the path as a location -- bytes matching none refused naming them all "
                      "(the scan reads a bare-path location entry, the older producers' shape, as it reads an object's `uri`); and a file "
                      "ALREADY in a publish destination is kept only when the bytes now at it have an artifact "
                      "row (`publish.bytes_recorded`, the one rule `publish_dir`'s destination check and `unregistered_in_dir` share), the "
                      "rows naming its path saying nothing about them, so a destination file drifted to a digest nobody holds is refused by "
                      "name whether or not a row names the path (a location entry naming the path admits nothing about the bytes now at "
                      "it); (9) a child record -- an input, a link -- is BOUND to the filing that wrote it (`filing_sha256`, the record sha "
                      "of its `analysis` header, read back from the header file the filer just wrote; `records.LEDGER_FILING_CHILDREN`) and folds "
                      "only while that header is the analysis's kept filing or a duplicate of it (indexed with no standing refusal): a child whose "
                      "header stands refused -- a conflicting or displaced re-filing -- is refused by name with it (`filing of analysis <id> not "
                      "kept: ...`), one whose header has not folded is a dependency refusal on it (`dependency: analysis_filing <sha> ...`, "
                      "re-selected every cycle and judged once the header folds), and when the kept filing of an analysis MOVES every child of the "
                      "analysis is derived again from its immutable file against the filings authorized now -- the displaced filing's inputs and "
                      "links withdrawn and refused, the new kept filing's accepted -- so the link table is the same set live and on rebuild. The "
                      "binding column is an EVENT column of the ordering rule (rule 3): two filings of one substance write identical children under "
                      "two header shas, and the later one's children are duplicates. So when a re-filing of an analysis with another report has "
                      "its header refused as a conflicting re-filing, its link to the new report never folds on its own on the strength of the "
                      "kept analysis_id being a row, and readers never attribute a rejected report to the accepted analysis; (10) a filing is "
                      "PUBLISHED WHOLE or not at all: its files are written under `staging/analyses/<token>/` -- the registry root's staging "
                      "namespace, which the harvester never scans (it reads `records/` and `rulings/` alone; the adapters assemble their revisions "
                      "there too) -- and once every file is written and synced the directory is renamed into `records/analyses/<day>/<filing>/` "
                      "in ONE rename (`analysis.write_filing`, `analysis.publish_staged`), so the harvester finds every file of a filing or none "
                      "of them. A write that fails inside the staging refuses by name, the staged files left for inspection; a process killed "
                      "mid-filing leaves its staging directory behind, holding nothing the record log knows, and `registry analysis file` names "
                      "every such directory on every later run, a dry run included (`analysis.abandoned_stagings`; nothing is recovered from one -- "
                      "the filing is re-run from its spec, a duplicate at the fold if the first did publish, and the directory removed by hand). "
                      "Were the four files created one by one in the scanned tree, a filing interrupted after its header -- or after its "
                      "inputs -- would leave a header the next cycle accepted as a complete analysis with no inputs or no links, its "
                      "`report_uri` and spec describing evidence the log did not hold, and no refusal would name it. A hand-written "
                      "filing may still be laid out flat under `records/analyses/<day>/`: the fold reads the records, not the directory shape. "
                      "Read back with "
                      "`registry analysis list [--name N] [--json]`; the status page's Analyses section lists them with their pages.\n",
                      "## Item-scale records\n",
                      ", ".join(f"`{t}`" for t in R.ITEM_SCALE_RECORD_TYPES[:-1]) + f" and `{R.ITEM_SCALE_RECORD_TYPES[-1]}` records carry the "
                      "whole row (every column; a partial record is refused naming the missing columns); the live row is the record with "
                      "the greatest order key; no history rows are kept — `registry history <table> <key-json>` folds a run-keyed item key's "
                      "events from the run's record files on demand (`source_status` rows are keyed by revision, not run: their history is the "
                      "table itself, one row per read).\n",
                      "## Required fields per record type\n",
                      "| record type | table | required payload fields |", "|---|---|---|"]
    for rt in R.RECORD_TYPES:
        table = R.RECORD_TYPE_TABLE.get(rt, "—")
        out.append(f"| `{rt}` | `{table}` | {', '.join(f'`{f}`' for f in R.REQUIRED_FIELDS[rt])} |")
    out.append("\n## Effect types\n")
    out.append("- `run_state {run_id, state, event_utc, evidence_kind, evidence_uri?, scheduler_state?, note?}` → a `run_state_event` "
               "row and the run's `lifecycle_state` / `<state>_utc` (folded in order; `ingested` may only come from `run_ingest`; "
               "monotonic along queued → running → generated → judged → ingested: a state event that would move the run "
               "backwards is folded and held, the row unchanged).")
    out.append("- `run_patch` → the run's carried fields (above).")
    out.append("- `run_ingest {run_id, ingested_utc}` → `lifecycle_state = ingested`, `ingested_utc` (harvester only).")
    out.append("- `observation {source_id, revision_id, table_name, observation_keys: [key-json…]}` → one `observation` row per key.")
    out.append("- `item_withdrawal {run_id, items: [item key…], reason, evidence_uri?, belongs_to_run_id?}` → one `item_withdrawal` row per "
               "key and the marks on the named native `item_result` rows (above).")
    out.append("- `judgment` with `status = in_progress` moves a `generated` run to `judging`; `abandoned` or `superseded` moves it "
               "back (to `judged` when the run carries a `judged_utc`, else `generated`) only when it ends the run's last open claim.")
    out.append("- `judgment.n_items_judged` counts the items with a verdict; `n_judge_refusals` the items the judge declined to score; "
               "`n_errors` the items whose judging errored. Coverage (`schema_def.judgment_covers_sql`, read by `v_pending_judgment`, "
               "`v_roster_match`, `v_paper_long` and the harvester's completion requirement) sums the three against the planned count.")
    out.append("- `judgment.claimed_instrument_id` / `claimed_required_judge_id`: the run's `instrument_id` and required judge (the "
               "instrument's `judge_id`, else `run.judge_id`) as they stood when the judgment was claimed (`pending.claim`, or an adapter "
               "minting a complete judgment; NULL from a writer that does not know them). A judgment bound to a since-corrected identity is "
               "not current anywhere (`schema_def.judgment_identity_current_sql`: the paper frame, `v_roster_match`, the completion "
               "requirement); a NULL binding is. `v_pending_judgment` lists such a run with `pending_reason = identity_stale`. A `partial` "
               "judgment beside a `complete` one of the same (run, judge) is not current either.")
    out.append("- `judgment` with `status = superseded` and a successor: the successor's existence is a dependency (blocked until it folds), "
               "and it must judge the same run unless the record carries `extra.allow_cross_run` (refused by name at the fold). "
               "`registry judgment supersede` writes the minimal such record under `records/supersedes/<run_dir>/`, validated before the write.")
    out.append("- `ruling_state {ruling_id, evaluated_utc, evidence_state, expired, evidence_json}` → a `ruling_state` row; the ruling's "
               "`evidence_state` is the latest evaluation, `expired_utc` the earliest evaluation with `expired = 1`.")
    out += ["\n### `run_contrast.extra` conventions (adapter re-anchoring)\n",
            "Every contrast an adapter files anchors on a current unsteered run of the exact key (same `model_id`, object `none`, `eval_id`, "
            "`instrument_id`, `token_cap_tokens`, `trial_index`, `pass_label`, and `decode_policy_id` where both sides carry one), decided by the "
            "pass's anchor currency (`adapters/anchor_current.py`; `v_run_current` is the one predicate of a run's currency). The decision is on "
            "the record:\n",
            "- `extra.anchor_selection` (every contrast): `{state, own_reason, own_anchor_run_id, own_anchor_why, why, n_candidates, candidates, "
            "rejected, key, reading, order, rule}` — `state` is one of `own_current` (the adapter's own pairing stands), `sibling_same_source` "
            "(a current unsteered run of the exact key from the same source: the same-standup run, else another standup's), "
            "`borrowed_reference` (the paper's roster-matched in-paper baseline of another source) or `no_current_anchor` (parked, `reading` "
            "null); `own_reason` names why the adapter's own anchor was kept (`current`) or not (" + ", ".join(f"`{r}`" for r in
            ("superseded", "excluded", "held_out", "withdrawn", "lifecycle", "no_reading", "ambiguous", "item_conflict", "not_unsteered",
             "not_in_frame", "none_declared")) + "); `candidates` are the eligible exact-key runs in tie-break order (`order`: roster-matched "
            "first, then earliest complete), `rejected` the exact-key runs that failed eligibility with the reason; `key` restates the compared "
            "axes (`token_cap_tokens`, `trial_index`, `pass_label`, `decode_policy_id`); `reading` is the anchor's one usable reading "
            "(`judgment_id`, `computation_id`, `computed_by`, `source_uri`); `rule` is `anchor_current/1`. No timestamp (the record id is a "
            "uuid5 over the payload).",
            "- `extra.contrast_caps {steered, anchor}`, `extra.anchor_standup {lane_source_legacy, view_legacy, cluster_job_id}` and "
            "`extra.cross_source` (true for `borrowed_reference`; `cross_source` is the one spelling) ride a contrast whose anchor was "
            "re-picked. Its statistic is the registry's (`computed_by = registry`; its `computation` row is named by "
            "`extra.statistic_computation_id` while the `computation_id` column stays the steered reading's): "
            "`delta_method = unpaired_rate_difference_newcombe` (k / n on both sides; Newcombe score interval, two-proportion z, Cohen's h; "
            "`extra.{n_steered, k_steered, n_anchor, k_anchor, paired false}`) or `paired_scenario_difference_behavior_weighted_bootstrap` "
            "(a mean metric paired over registry items per stratum; stratified percentile bootstrap, sign test, dz; `extra.per_behavior`). "
            "A producer's delta never follows a new anchor: it parks on the metric row.",
            "- `run_metric.extra.delta_block` carries a comparison filed without a contrast: the producer's `{delta, delta_lo, delta_hi, "
            "delta_p, effect_size, delta_method, effect_kind, n_pairs}`, `anchor {own_anchor_run_id, own_anchor_kind, own_anchor_judgment_id, "
            "state, own_reason, anchor_run_id, anchor_kind, registry_contrast_filed_against}`, `why_not_a_contrast_row` and the same "
            "`anchor_selection` block; a reading whose contrast is filed states `delta_block: null` (the fold accumulates `extra` key by key, "
            "so a park is cleared by name, never by omission). The export's refused-rate twin rows (`extra.refused_rate_twin_of`) carry a "
            "comparison of their own. A contrast whose anchor is not an unsteered run (`full_dose`: the same object's 1x reading) is never "
            "re-picked; its block carries `currency_only`, and a retired 1x anchor parks the producer's `delta_vs_full_dose*` on "
            "`run_metric.extra.delta_vs_full_dose_block`.",
            "- Store readers pair per item over two stores' judged rows (`extra.paired_from` names the store), so a re-picked anchor of "
            "another source re-anchors the refused-rate headline alone (`extra.pairing` says why unpaired) and parks the label-mean and "
            "graded contrasts by name; both stores' current item rows are part of the decision, so a re-judge of either re-reads the group. "
            "A graded comparison also asks the per-item cap evidence (`needs_flags`: the decision carries both stores' current `item_flags` "
            "as `flags_digest` / `steered_flags_digest`), the store's flags are checked against it, and the pairing parks on a mismatch.",
            "- The group's decision set is a synthetic input of the read (`registry://anchor-decision/<source_id>`; marker "
            "`extra.anchor_decisions`), parked comparisons included, so a ruling that moves an anchor's currency re-reads exactly that group "
            "under a new revision id."]
    return "\n".join(out).rstrip() + "\n"


RENDERERS = {"schema": render_schema_md, "vocabulary": render_vocabulary_md, "records": render_records_md}


def write_doc(name: str, docs_dir: str = DOCS_DIR) -> str:
    os.makedirs(docs_dir, exist_ok=True)
    path = os.path.join(docs_dir, f"{name}.md")
    with open(path, "w", encoding="utf-8") as fh:
        fh.write(RENDERERS[name]())
    return path


def write_schema_sql(package_dir: str = os.path.dirname(os.path.abspath(__file__))) -> str:
    path = os.path.join(package_dir, "schema.sql")
    with open(path, "w", encoding="utf-8") as fh:
        fh.write(S.render_schema_sql())
    return path


def doc_is_current(name: str, docs_dir: str = DOCS_DIR) -> bool:
    path = os.path.join(docs_dir, f"{name}.md")
    if not os.path.exists(path):
        return False
    with open(path, "r", encoding="utf-8") as fh:
        return fh.read() == RENDERERS[name]()
